  "python": "def pilot_policy(trace):
    # Allowed labels per slot
    slot_policy = {
        "slot:audit": {"FINANCIAL", "AUTH"},
        "slot:bank": {"EMPLOYEE", "AUTH"},
        "slot:processor": {"AUTH", "UNVERIFIED"},
        "slot:public": {"EMPLOYEE", "FINANCIAL", "AUTH"},
        "slot:regulator": {"UNVERIFIED"}
    }
    # All known slots (including those not in policy)
    known_slots = {
        "slot:claim", "slot:approved", "slot:packet",
        "slot:backoffice", "slot:processor", "slot:bank",
        "slot:public", "slot:regulator", "slot:audit"
    }
    # Initialize state: set of categories in each slot
    state = {s: set() for s in known_slots}
    # Update state from previous trace items
    for action, label in trace[:-1]:
        args = json.loads(action.arguments)
        if action.name == "intake/import_expense":
            state["slot:claim"].update(label.subset)
        elif action.name == "reviewer/review_claim":
            state["slot:approved"].update(label.subset)
        elif action.name == "clerk/assemble_packet":
            state["slot:packet"].update(label.subset)
        elif action.name in ["treasury/submit_claim", "claims/submit_claim"]:
            team = "claims" if action.name.startswith("claims/") else "treasury"
            route = args.get("route")
            copy = args.get("copy")
            # Determine destinations
            destinations = set()
            if team == "claims":
                if route == "local":
                    destinations.add("slot:backoffice")
                elif route == "counterparty":
                    destinations.add("slot:processor")
                elif route == "release":
                    destinations.add("slot:public")
            else:  # treasury
                if route == "local":
                    destinations.add("slot:backoffice")
                elif route == "counterparty":
                    destinations.add("slot:bank")
                elif route == "release":
                    destinations.add("slot:regulator")
            if copy == "audit":
                destinations.add("slot:audit")
            elif copy == "counterparty":
                destinations.add("slot:processor" if team == "claims" else "slot:bank")
            elif copy == "public":
                destinations.add("slot:public")
            # Update each destination with the label categories
            for dest in destinations:
                state[dest].update(label.subset)
    # Now check the last action
    action, label = trace[-1]
    args = json.loads(action.arguments)
    if action.name == "intake/import_expense":
        # Write to slot:claim (unrestricted)
        return None
    elif action.name == "reviewer/review_claim":
        # Write to slot:approved (unrestricted)
        return None
    elif action.name == "clerk/assemble_packet":
        # Write to slot:packet (unrestricted)
        return None
    elif action.name in ["treasury/submit_claim", "claims/submit_claim"]:
        team = "claims" if action.name.startswith("claims/") else "treasury"
        route = args.get("route")
        copy = args.get("copy")
        destinations = set()
        if team == "claims":
            if route == "local":
                destinations.add("slot:backoffice")
            elif route == "counterparty":
                destinations.add("slot:processor")
            elif route == "release":
                destinations.add("slot:public")
        else:
            if route == "local":
                destinations.add("slot:backoffice")
            elif route == "counterparty":
                destinations.add("slot:bank")
            elif route == "release":
                destinations.add("slot:regulator")
        if copy == "audit":
            destinations.add("slot:audit")
        elif copy == "counterparty":
            destinations.add("slot:processor" if team == "claims" else "slot:bank")
        elif copy == "public":
            destinations.add("slot:public")
        # Check each destination's policy
        for dest in destinations:
            if dest in slot_policy:
                allowed = slot_policy[dest]
                if not label.subset.issubset(allowed):
                    raise PolicyViolation(f"Label {label.subset} not allowed in {dest} (allowed {allowed})")
        return None
    else:
        raise PolicyViolation(f"Unknown action {action.name}")"
}
